#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
static ll n,m; static mt19937_64 rng(987654321ULL);
static inline ll md(ll a){a%=n; if(a<0)a+=n; return a;}
static inline ll dst(ll a,ll b){ll d=md(a-b); return min(d,n-d);}
static inline ll Fv(ll u,ll k){if(u+k<=m)return 2*max(u,k); return n-2*min(u,k);}
struct Comp{ll clo,chi,klo,khi;}; typedef pair<ll,ll> Iv;
static inline void addIv(vector<Iv>&v,ll lo,ll hi){if(lo<=hi)v.push_back(Iv(lo,hi));}
static vector<Iv> normIv(vector<Iv> v){sort(v.begin(),v.end());vector<Iv> r;for(size_t i=0;i<v.size();i++){if(!r.empty()&&v[i].first<=r.back().second+1){if(v[i].second>r.back().second)r.back().second=v[i].second;}else r.push_back(v[i]);}return r;}
static vector<Iv> arcIv(ll x,ll r){vector<Iv> s;if(r<0)return s;if(r>=m){s.push_back(Iv(0,n-1));return s;}ll lo=x-r,hi=x+r;if(lo<0){addIv(s,lo+n,n-1);addIv(s,0,hi);}else if(hi>=n){addIv(s,lo,n-1);addIv(s,0,hi-n);}else addIv(s,lo,hi);return s;}
static vector<Iv> subIv(const vector<Iv>&A,const vector<Iv>&B){vector<Iv> res;for(size_t i=0;i<A.size();i++){vector<Iv> cur;cur.push_back(A[i]);for(size_t j=0;j<B.size();j++){vector<Iv> nx;for(size_t t=0;t<cur.size();t++){Iv c=cur[t],b=B[j];if(b.second<c.first||b.first>c.second){nx.push_back(c);continue;}addIv(nx,c.first,b.first-1);addIv(nx,b.second+1,c.second);}cur.swap(nx);}for(size_t t=0;t<cur.size();t++)res.push_back(cur[t]);}return normIv(res);}
static vector<Iv> rangeIv(ll x,ll lo,ll hi){if(hi<lo)return vector<Iv>();vector<Iv> A=arcIv(x,hi);if(lo<=0)return A;vector<Iv> B=arcIv(x,lo-1);return subIv(A,B);}
static vector<Comp> conC(ll x,ll v){vector<Comp> r;if(v%2==0){ll w=v/2,klo=1,khi=min(w,m-w);if(klo<=khi){ll c1=md(x-w),c2=md(x+w);r.push_back(Comp{c1,c1,klo,khi});if(c2!=c1)r.push_back(Comp{c2,c2,klo,khi});}if(w>=1&&w<=m){vector<Iv> iv=arcIv(x,min(w,m-w));for(size_t i=0;i<iv.size();i++)r.push_back(Comp{iv[i].first,iv[i].second,w,w});}}else{ll w=(n-v)/2;if(w>=1&&w<=m){ll klo=max(w,m+1-w),khi=m;if(klo<=khi){ll c1=md(x-w),c2=md(x+w);r.push_back(Comp{c1,c1,klo,khi});if(c2!=c1)r.push_back(Comp{c2,c2,klo,khi});}vector<Iv> iv=rangeIv(x,max(w,m+1-w),m);for(size_t i=0;i<iv.size();i++)r.push_back(Comp{iv[i].first,iv[i].second,w,w});}}return r;}
static vector<Comp> interC(const vector<Comp>&A,const vector<Comp>&B){vector<Comp> r;for(size_t i=0;i<A.size();i++){const Comp&a=A[i];bool aP=(a.clo==a.chi);for(size_t j=0;j<B.size();j++){const Comp&b=B[j];bool bP=(b.clo==b.chi);if(aP&&bP){if(a.clo!=b.clo)continue;ll lo=max(a.klo,b.klo),hi=min(a.khi,b.khi);if(lo<=hi)r.push_back(Comp{a.clo,a.clo,lo,hi});}else if(aP){ll k=b.klo;if(k<a.klo||k>a.khi)continue;if(a.clo<b.clo||a.clo>b.chi)continue;r.push_back(Comp{a.clo,a.clo,k,k});}else if(bP){ll k=a.klo;if(k<b.klo||k>b.khi)continue;if(b.clo<a.clo||b.clo>a.chi)continue;r.push_back(Comp{b.clo,b.clo,k,k});}else{if(a.klo!=b.klo)continue;ll lo=max(a.clo,b.clo),hi=min(a.chi,b.chi);if(lo<=hi)r.push_back(Comp{lo,hi,a.klo,a.klo});}}}return r;}
static void normC(vector<Comp>&cs){map<ll,vector<Iv> >P,Q;for(size_t i=0;i<cs.size();i++){if(cs[i].clo==cs[i].chi)P[cs[i].clo].push_back(Iv(cs[i].klo,cs[i].khi));else Q[cs[i].klo].push_back(Iv(cs[i].clo,cs[i].chi));}vector<pair<ll,vector<Iv> > >Pv,Qv;for(auto it=P.begin();it!=P.end();++it)Pv.push_back(make_pair(it->first,normIv(it->second)));for(auto it=Q.begin();it!=Q.end();++it)Qv.push_back(make_pair(it->first,normIv(it->second)));vector<Comp> res;for(size_t i=0;i<Pv.size();i++){ll c0=Pv[i].first;vector<Iv> all;for(size_t j=0;j<Pv[i].second.size();j++){vector<Iv> cur;cur.push_back(Pv[i].second[j]);for(size_t t=0;t<Qv.size();t++){ll k0=Qv[t].first;bool in=false;for(size_t s=0;s<Qv[t].second.size();s++)if(c0>=Qv[t].second[s].first&&c0<=Qv[t].second[s].second)in=true;if(!in)continue;vector<Iv> nx;for(size_t s=0;s<cur.size();s++){Iv c=cur[s];if(k0<c.first||k0>c.second){nx.push_back(c);continue;}addIv(nx,c.first,k0-1);addIv(nx,k0+1,c.second);}cur.swap(nx);}for(size_t s=0;s<cur.size();s++)all.push_back(cur[s]);}all=normIv(all);for(size_t j=0;j<all.size();j++)res.push_back(Comp{c0,c0,all[j].first,all[j].second});}for(size_t t=0;t<Qv.size();t++)for(size_t s=0;s<Qv[t].second.size();s++)res.push_back(Comp{Qv[t].second[s].first,Qv[t].second[s].second,Qv[t].first,Qv[t].first});cs.swap(res);}
static ll cntArc(ll clo,ll chi,ll x,ll r){if(r<0)return 0;if(r>=m)return chi-clo+1;ll lo=x-r,hi=x+r,c=0;if(lo<0){c+=max(0LL,min(chi,n-1)-max(clo,lo+n)+1);c+=max(0LL,min(chi,hi)-max(clo,0LL)+1);}else if(hi>=n){c+=max(0LL,min(chi,n-1)-max(clo,lo)+1);c+=max(0LL,min(chi,hi-n)-max(clo,0LL)+1);}else c+=max(0LL,min(chi,hi)-max(clo,lo)+1);return c;}
static ll ctb(ll x,ll r,const Comp&c,ll u,ll t1,ll t2,bool ev,ll w){ll tot=0;if(c.clo==c.chi){if(r==2*u){ll lo=max(c.klo,1LL),hi=min(c.khi,min(u,m-u));if(lo<=hi)tot+=hi-lo+1;}if(r==n-2*u){ll lo=max(c.klo,max(u,m+1-u)),hi=min(c.khi,m);if(lo<=hi)tot+=hi-lo+1;}if(ev){if(w>=c.klo&&w<=c.khi&&w>=u+1&&w<=m-u)tot++;}else{if(w>=c.klo&&w<=c.khi&&w>=m+1-u&&w<=u-1)tot++;}}else{ll k0=c.klo;if(r==2*k0)tot+=cntArc(c.clo,c.chi,x,t1);if(r==n-2*k0)tot+=(c.chi-c.clo+1)-cntArc(c.clo,c.chi,x,t2-1);if(ev){if(w>=k0+1&&w<=m-k0){ll cp=md(x+w),cm=md(x-w);if(cp>=c.clo&&cp<=c.chi)tot++;if(w>0&&cm>=c.clo&&cm<=c.chi)tot++;}}else{if(w>=m+1-k0&&w<=k0-1){ll cp=md(x+w),cm=md(x-w);if(cp>=c.clo&&cp<=c.chi)tot++;if(w>0&&cm>=c.clo&&cm<=c.chi)tot++;}}}return tot;}
struct Score{ll me,nb,ms;};
static bool bet(const Score&a,const Score&b){if(a.me!=b.me)return a.me<b.me;if(a.nb!=b.nb)return a.nb<b.nb;return a.ms<b.ms;}
static Score eval(ll x,const vector<Comp>&cs){int nc=cs.size();vector<ll> U(nc),T1(nc),T2(nc);vector<ll> rs;for(int i=0;i<nc;i++){if(cs[i].clo==cs[i].chi){U[i]=dst(x,cs[i].clo);T1[i]=T2[i]=0;}else{ll k=cs[i].klo;T1[i]=min(k,m-k);T2[i]=m+1-T1[i];U[i]=0;}}for(int i=0;i<nc;i++){const Comp&c=cs[i];if(c.clo==c.chi){ll u=U[i];ll b[11]={c.klo,c.khi,u,u+1,u-1,m-u,m-u+1,m-u-1,m+1-u,m+1-u+1,m+1-u-1};for(int j=0;j<11;j++)for(ll d=-1;d<=1;d++){ll k=b[j]+d;if(k>=1&&k<=m){rs.push_back(2*k);rs.push_back(n-2*k);}}rs.push_back(Fv(u,c.klo));rs.push_back(Fv(u,c.khi));}else{ll k0=c.klo,t1=T1[i],t2=T2[i];rs.push_back(2*k0);rs.push_back(n-2*k0);ll b[13]={t1,t1+1,t1-1,t2,t2+1,t2-1,k0,k0+1,k0-1,m-k0,m-k0+1,m+1-k0,m+1-k0-1};for(int j=0;j<13;j++)for(ll d=-1;d<=1;d++){ll u=b[j]+d;if(u>=0&&u<=m){rs.push_back(2*u);rs.push_back(n-2*u);}}ll cc[2]={c.clo,c.chi};for(int j=0;j<2;j++){ll u1=md(cc[j]-x),u2=md(x-cc[j]);for(ll d=-1;d<=1;d++){if(u1+d>=0&&u1+d<=m){rs.push_back(2*(u1+d));rs.push_back(n-2*(u1+d));}if(u2+d>=0&&u2+d<=m){rs.push_back(2*(u2+d));rs.push_back(n-2*(u2+d));}}}rs.push_back(Fv(dst(x,c.clo),k0));rs.push_back(Fv(dst(x,c.chi),k0));}}sort(rs.begin(),rs.end());rs.erase(unique(rs.begin(),rs.end()),rs.end());if(rs.size()>400){vector<ll> t;for(size_t i=0;i<400;i++)t.push_back(rs[i*rs.size()/400]);rs.swap(t);}Score s;s.me=0;s.nb=0;s.ms=0;for(size_t j=0;j<rs.size();j++){ll r=rs[j];if(r<1||r>n-1)continue;bool ev=(r%2==0);ll w=ev?r/2:(n-r)/2;ll sz=0;int ncn=0;bool aP=true;for(int i=0;i<nc;i++){ll t=ctb(x,r,cs[i],U[i],T1[i],T2[i],ev,w);if(t>0){sz+=t;ncn++;if(cs[i].clo!=cs[i].chi)aP=false;}}if(sz==0)continue;ll ef=aP?min(sz,2LL*ncn):sz;if(ef>s.me)s.me=ef;if(sz>s.ms)s.ms=sz;if(ef>=2)s.nb++;}return s;}
static set<ll> bad;
static ll choose(const vector<Comp>&cs,ll tot){vector<ll> xs,ct;auto add=[&](ll v){xs.push_back(md(v));};for(size_t i=0;i<cs.size();i++){const Comp&c=cs[i];if(c.clo==c.chi){ll c0=c.clo;ct.push_back(c0);add(c0);add(c0+m);add(c0+m+1);ll cnt=c.khi-c.klo+1;if(cnt<=10){for(ll k=c.klo;k<=c.khi;k++){add(c0+k);add(c0-k);add(c0+k+m);add(c0-k+m);add(c0+k+m+1);add(c0-k+m+1);}}else{ll kk[3]={c.klo,c.khi,(c.klo+c.khi)/2};for(int j=0;j<3;j++){add(c0+kk[j]);add(c0-kk[j]);add(c0+kk[j]+m);add(c0-kk[j]+m);}}}else{ll k0=c.klo,t1=min(k0,m-k0),L=c.chi-c.clo+1,h=L/2;add(c.clo);add(c.chi);add(c.clo+h);add(c.clo+h+m);add(c.clo+h+m+1);add(c.clo+t1);add(c.chi-t1);add(c.clo-t1-1);add(c.chi+t1+1);add(c.clo+t1+1);add(c.chi-t1-1);add(c.clo+h-1-t1);add(c.clo+h+t1);add(c.clo+h-1-m-t1);add(c.clo+h-m-1+t1);if(L<=10){for(ll cc=c.clo;cc<=c.chi;cc++){ct.push_back(cc);add(cc+k0);add(cc-k0);add(cc+k0+m);add(cc-k0+m);}}else{ll cc[3]={c.clo,c.chi,c.clo+h};for(int j=0;j<3;j++){ct.push_back(cc[j]);add(cc[j]+k0);add(cc[j]-k0);add(cc[j]+k0+m);add(cc[j]-k0+m);add(cc[j]+k0+m+1);add(cc[j]-k0+m+1);}}}}sort(ct.begin(),ct.end());ct.erase(unique(ct.begin(),ct.end()),ct.end());if(ct.size()>10)ct.resize(10);for(size_t i=0;i<ct.size();i++)for(size_t j=i+1;j<ct.size();j++){ll d=md(ct[j]-ct[i]),mid=md(ct[i]+d/2);add(mid);add(mid+m);add(mid+m+1);}add(0);add(m);add(m+1);for(int i=0;i<12;i++)add((ll)(rng()%n));sort(xs.begin(),xs.end());xs.erase(unique(xs.begin(),xs.end()),xs.end());if(xs.size()>250){vector<ll> t;for(size_t i=0;i<250;i++)t.push_back(xs[i*xs.size()/250]);xs.swap(t);}Score bs;bs.me=LLONG_MAX;bs.nb=LLONG_MAX;bs.ms=LLONG_MAX;ll bx=-1;for(size_t i=0;i<xs.size();i++){ll x=xs[i];if(bad.count(x))continue;Score s=eval(x,cs);if(bet(s,bs)){bs=s;bx=x;}if(bs.me<=1)break;}if(bs.me>=tot){ll lim=min(n,(ll)4000);for(ll x=0;x<lim;x++){if(bad.count(x))continue;Score s=eval(x,cs);if(bet(s,bs)){bs=s;bx=x;}if(bs.me<=1)break;}}if(bx<0){for(ll x=0;x<n;x++)if(!bad.count(x)){bx=x;break;}}if(bx<0)bx=0;return bx;}
int main(){ios::sync_with_stdio(false);cin.tie(0);if(!(cin>>n))return 0;m=(n-1)/2;vector<Comp> cs;bool first=true;ll prevTot=-1,prevX=-1;while(true){ll tot=0;if(!first){normC(cs);for(size_t i=0;i<cs.size();i++)tot+=(cs[i].chi-cs[i].clo+1)*(cs[i].khi-cs[i].klo+1);if(tot==0)return 0;if(prevTot>=0&&tot==prevTot&&prevX>=0)bad.insert(prevX);if(tot==1){ll c0=cs[0].clo,k0=cs[0].klo;ll a=md(c0-k0)+1,b=md(c0+k0)+1;cout<<"! "<<a<<" "<<b<<"\n";cout.flush();return 0;}}ll x=first?0:choose(cs,tot);cout<<"? "<<(x+1)<<"\n";cout.flush();ll v;if(!(cin>>v))return 0;if(v<0)return 0;vector<Comp> cc=conC(x,v);if(first){cs=cc;first=false;}else cs=interC(cs,cc);if(cs.empty())return 0;prevTot=tot;prevX=x;}return 0;}
